entries[84406] = { ["name"] = "Authentische Junioreningenieursbrille", ["text"] = "Wirken in 1.5 sek. 3\nTools: Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (8), Hessonit (2), Primitives Leder (2)\nKopf Stoff\n19 Rüstung\nHaltbarkeit 40 / 40\nAnlegen: Lässt Euch talentierter und attraktiver erscheinen." }
entries[84408] = { ["name"] = "R19-Bedrohungsfinder", ["text"] = "Wirken in 1.5 sek. 5\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (6), Eine Handvoll Obsidiumbolzen (6), Alazit (2)\nR19-Bedrohungsfinder\n80\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den Distanztrefferwert um 88 .\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[84409] = { ["name"] = "Instabiles Zephyriumsprengpaket", ["text"] = "Wirken in 1.5 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Obsidiumbolzen , Elektrifizierter Äther (2)\nBenötigt Ingenieurskunst\n(425)\nBenutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 400 im Schlossknacken benötigen" }
entries[84410] = { ["name"] = "Sicherungshebelentfernungssatz", ["text"] = "Wirken in 1.5 sek. 5\nTools: Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (10)\nSicherungshebelentfernungssatz\n80\nBenutzen: Entfernt den Sicherungsmechanismus eines Bogens oder einer Schusswaffe, sodass das Distanztempo der Fernkampfwaffe um 88 erhöht wird.\n\nDurch das Entfernen der Sicherung einer Fernkampfwaffe wird diese seelengebunden." }
entries[84411] = { ["name"] = "Hochleistungsbolzenschusspistole", ["text"] = "Wirken in 4 sek. 5\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (4)\nHochleistungsbolzenschusspistole\nWird bei Benutzung gebunden\nBenötigt Ingenieurskunst\n(450)\nBenutzen: Feuert einige geladene Bolzen auf einen Feind ab und verursacht so 10180 Schaden, ebenso wird ein gewirkter Zauber kurzzeitig unterbrochen. Verbraucht mit jedem Schuss eine Handvoll Obsidiumbolzen. (2 Min Abklingzeit)\n\"Fast so schwer zu bedienen wie herzustellen.\"" }
entries[84412] = { ["name"] = "Persönlicher Weltenzerstörer", ["text"] = "Wirken in 1.5 sek. 5\nTools: Hochleistungsbolzenschusspistole , Schmiedehammer\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (8)\nPersönlicher Weltenzerstörer\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren persönlichen Weltenzerstörer beschwören oder wieder freigeben." }
entries[84413] = { ["name"] = "Entwaffneter mechanischer Begleiter", ["text"] = "Wirken in 1.5 sek. 5\nTools: Hochleistungsbolzenschusspistole , Bogenlichtschraubenschlüssel\nReagenzien:\nObsidiumbarren (12), Eine Handvoll Obsidiumbolzen (4), Elektrifizierter Äther (8), Jaspis (2)\nEntwaffneter mechanischer Begleiter\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren entwaffneten mechanischen Begleiter beschwören oder wieder freigeben." }
entries[84415] = { ["name"] = "Ködermeister Spinnerkasten", ["text"] = "Wirken in 5 sek. 5\nTools: Schmiedehammer , Hochleistungsbolzenschusspistole\nReagenzien:\nElementiumbarren (20), Eine Handvoll Obsidiumbolzen (4)\nKödermeister Spinnerkasten\nWird beim Anlegen gebunden\n36 Platz Angelkiste" }
entries[84416] = { ["name"] = "Elementiumwerkzeugkasten", ["text"] = "Wirken in 5 sek. 5\nTools: Schmiedehammer\nReagenzien:\nElementiumbarren (15), Flüchtige Erde (12)\nElementiumwerkzeugkasten\nWird beim Anlegen gebunden\n36 Platz Ingenieurstasche\n\"Möglicherweise der schönste Werkzeugkasten, der jemals erschaffen wurde, mit goldenen Intarsien.\"" }
entries[84417] = { ["name"] = "Unberechenbarer Donnerstock", ["text"] = "Wirken in 1.5 sek. 5\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nElektrifizierter Äther (2), Gehärteter Elementiumbarren (5), Flüchtiges Feuer (6)\nUnberechenbarer Donnerstock\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n1,917 - 3,562 Schaden Tempo 2.80\n(978.39 Schaden pro Sekunde)\n+268 Beweglichkeit\n+401 Ausdauer\nErhöht Eure kritische Trefferwertung um + 178.\nErhöht Eure Meisterschaftswertung um + 178.\nHaltbarkeit 100 / 100\n83" }
entries[84418] = { ["name"] = "Elementiumdrachling", ["text"] = "Wirken in 1.5 sek. 5\nTools: Schmiedehammer , Hochleistungsbolzenschusspistole\nReagenzien:\nEine Handvoll Obsidiumbolzen (2), Elektrifizierter Äther (8), Elementiumbarren (16), Glutseidenstoff (20)\nElementiumdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\nErhöht Eure Meisterschaftswertung um + 252.\n80\nBenötigt Ingenieurskunst\n(475)\nBenutzen: Aktiviert Euren Elementiumdrachling, der 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)" }
entries[84419] = { ["name"] = "Herausforderungsruf", ["text"] = "Sofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[84420] = { ["name"] = "Feinabgestimmter Kehlennadler", ["text"] = "Wirken in 1.5 sek. 5\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nObsidiumbarren (4), Elektrifizierter Äther (2), Gehärteter Elementiumbarren (5)\nFeinabgestimmter Kehlennadler\nWird beim Anlegen gebunden\nDistanz Armbrust\n1,986 - 3,689 Schaden Tempo 2.90\n(978.45 Schaden pro Sekunde)\n+268 Beweglichkeit\n+402 Ausdauer\nErhöht Eure kritische Trefferwertung um + 157.\nErhöht Eure Tempowertung um + 191.\nHaltbarkeit 75 / 75\n83" }
entries[84421] = { ["name"] = "Plünderang", ["text"] = "Wirken in 5 sek. 5\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Elementiumbarren (5), Elektrifizierter Äther (5)\nPlünderang\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(125)\nBenutzen: Sammelt die Beute von einem nahen Leichnam ein. (3 Sek. Abklingzeit)" }
entries[84424] = { ["name"] = "Unsichtbarkeitsfeld", ["text"] = "Wirken in 5 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt an einem Gürtel dauerhaft tausende winzige Spiegel an, die es Euch gestatten, außerhalb des Kampfes unsichtbar zu werden. Kann ein Mal alle 3 Min. ausgelöst werden.\n\nKann nur an Eurem eigenen Gürtel angebracht werden und er wird dadurch seelengebunden. Zur Benutzung wird eine Ingenieursfertigkeit von mindestens 450 benötigt." }
entries[84425] = { ["name"] = "Pappkamerad", ["text"] = "Wirken in 5 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt an Euren Gürtel permanent ein winziges Gerät an, welches es Euch gestattet, einen Pappkameraden aufzustellen, den Gegner angreifen werden. Hält 15 Sek. lang an. Kann nur ein Mal alle 5 Min. ausgelöst werden.\n\nKann nur an Eurem eigenen Gürtel angebracht werden und durch das Anbringen wird der Gegenstand seelengebunden. Zur Benutzung wird eine Ingenieursfertigkeit von mindestens 450 benötigt." }
entries[84426] = { ["name"] = "Teufelsatem", ["text"] = "Nahkampfreichweite\nWirken in 2.5 sek.\nFügt Gegnern in einem kegelförmigen Bereich vor dem Zaubernden Feuerschaden zu." }
entries[84427] = { ["name"] = "Geerdeter Plasmaschild", ["text"] = "Wirken in 5 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt an einem Gürtel dauerhaft geerdete Plasmageneratoren an, die es Euch gestatten, einen machtvollen Schild zu aktivieren, der ( 14400 * 4.5) bis ( 17600 * 4.5) Schaden absorbiert. Kann nur ein Mal alle 5 Min. genutzt werden.\n\nKann nur an Euren eigenen Gürtel angebracht werden und er wird dadurch seelengebunden. Zur Benutzung wird eine Ingenieursfertigkeit von mindestens 450 benötigt." }
entries[84428] = { ["name"] = "Gnomisches Röntgenzielfernrohr", ["text"] = "Wirken in 1.5 sek. 4\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nGehärteter Elementiumbarren (2), Traumsmaragd (2)\nGnomisches Röntgenzielfernrohr\n80\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit einem Bogen oder einer Schusswaffe, sodass manchmal die Distanzangriffskraft dieser Waffe 10 Sek. lang um 800 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[84429] = { ["name"] = "Goblinbarbecue", ["text"] = "Wirken in 1.5 sek.\nTools: Hochleistungsbolzenschusspistole , Bogenlichtschraubenschlüssel\nReagenzien:\nElementiumbarren (2), Zähes Fleisch (2), Lavaschuppenfilet (2)\n80\nBenötigt Kochkunst\n(475)\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Goblinbarbecuefestmahl her! Stellt im Verlauf von 30 Sek. 67500 Gesundheit und ( 7500 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 60 Ausdauer und ein für Euch nützlicher Wert wird um 60 erhöht." }
entries[84430] = { ["name"] = "Hitzebehandelter Spinnerbait", ["text"] = "Wirken in 1.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Obsidiumbolzen , Elementiumbarren (4), Flüchtiges Feuer\n(2)\nBenötigt Angeln\n(250)\nBenutzen: Bei Anwendung auf Eure Angelrute wird die Fähigkeit 'Angeln' 15 Minuten lang um 150 Punkte erhöht.\n\"Funktioniert sogar in Lava!\"" }
entries[84431] = { ["name"] = "Übermotorisierter Hühnerspalter", ["text"] = "Wirken in 1.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Elementiumbarren (12), Echtgold (2), Eine Handvoll Obsidiumbolzen (6), Elektrifizierter Äther (8), Chaoskugel\nÜbermotorisierter Hühnerspalter\nWird beim Anlegen gebunden\nDistanz Bogen\n2,164 - 4,020 Schaden Tempo 2.80\n(1,104 Schaden pro Sekunde)\n+302 Beweglichkeit\n+454 Ausdauer\nErhöht Eure kritische Trefferwertung um + 216.\nErhöht Eure Tempowertung um + 177.\nHaltbarkeit 100 / 100\n85" }
entries[84432] = { ["name"] = "Rückstoß 5000", ["text"] = "Wirken in 1.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Elementiumbarren (9), Echtgold (3), Haarfeiner Sprengstoffauslöser , Schäftung aus Walnussholz , Chaoskugel\nRückstoß 5000\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n2,164 - 4,020 Schaden Tempo 2.80\n(1,104 Schaden pro Sekunde)\n+282 Beweglichkeit\n+454 Ausdauer\nErhöht Eure kritische Trefferwertung um + 207.\nErhöht Eure Tempowertung um + 176.\n\nRoter Sockel\nSockelbonus: + 10 Beweglichkeit\n\nHaltbarkeit 100 / 100\n85" }
